"reconciliation_of_conflicting_operating_numbers": {
  "note": "Several operating numbers are given inconsistently even within a single source (the 2026-06-16 FAQ post). Each disputed figure below is pinned to an exact quote, its URL, and whether the text presents it as past, present, or future, per an explicit re-verification pass requested mid-research.",
  "hours_per_weekday": {
    "status": "GENUINE, UNRESOLVED INTERNAL CONTRADICTION within one document",
    "quotes": [
      {"text": "\"Every weekday, 8 hours a day from 9am to 5pm PT.\"", "faq_heading": "When is the Village live?", "tense": "present, as if already true on publish date", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"the agents currently run for 20 hours a week\"", "faq_heading": "How much do humans intervene?", "tense": "present (\"currently\")", "computed_hours_per_day": "20/5 = 4", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"over 15 now really quite capable agents running 4 hours a day\"", "faq_heading": "What is happening in the Village?", "tense": "present", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"watch the Village live (every weekday 10am-2pm PT)\"", "faq_heading": "What is happening in the Village?", "tense": "present", "note": "a 4-hour window, contradicting the 9am-5pm/8-hour window claimed elsewhere in the SAME post", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"It previously ran for fewer hours\" ... \"agents currently run for 20 hours a week\" ... \"perhaps eventually giving the agents a 24 hour continuous runtime\"", "note": "the post's own explicit past/present/future framing for this number", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"Village began running 8 hours/day (up from 4)\"", "note": "dated timeline EVENT, 13 days AFTER the FAQ was published", "date": "2026-06-29", "source": "https://theaidigest.org/village/timeline"}
    ],
    "most_likely_explanation_unconfirmed": "The 'When is the Village live?' FAQ answer was probably silently edited after 2026-06-29 to reflect the new 8-hour schedule, while the 'How much do humans intervene?' and 'What is happening in the Village?' answers were left with pre-change (4 hours/day) figures. No 'last updated' or revision-date marker is exposed anywhere on the rendered Substack page (checked directly; none found), so this edit history is inferred, not confirmed.",
    "comparison_against_theaidigest_org_village_landing_page": "Attempted directly, including a targeted check for embedded __NEXT_DATA__/JSON-LD/meta-tag numbers in the raw source. None were found in any fetch attempt — the page is fully client-rendered and every retrieval returned only a bare 'Loading village history...' placeholder with no numeric content anywhere in the retrievable HTML. This dossier therefore found NO basis to assert the live site and the FAQ disagree on hours/day specifically — that would require a number from the site that was never actually retrievable. This is a tool/rendering limitation, not a confirmed agreement or disagreement.",
    "unverified": true
  },
  "agent_count_now": {
    "status": "THREE DIFFERENT SNAPSHOTS, COMPLEMENTARY NOT CONTRADICTORY (each dated separately, consistent with growth)",
    "quotes": [
      {"text": "\"11 agents running concurrently\"", "period_described": "late 2025", "source": "https://aivillageblog.substack.com/p/what-we-learned-2025", "post_date": "2026-02-02"},
      {"text": "\"Since it began with four agents, the Village has grown to over 15 agents and counting.\"", "period_described": "2026-06-16 (as of publish)", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"over 15 now really quite capable agents running 4 hours a day\"", "period_described": "2026-06-16 (as of publish)", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16"},
      {"text": "\"The AI Village has run every weekday since April 2025, now running 27 agents for 8 hours a day.\"", "period_described": "2026-08-28 (as of publish)", "source": "https://aivillageblog.substack.com/p/work-on-the-ai-village", "post_date": "2026-08-28"}
    ],
    "conclusion": "11 -> over 15 -> 27 across three dates roughly four and two months apart is a coherent growth curve; none of these claims to describe the same moment, so they do not conflict with each other the way the hours-per-day figures do."
  },
  "memory_consolidation_cadence": {
    "status": "single consistent figure; no conflict found",
    "quote": "\"Therefore, every 40 actions the agent takes (40 clicks, messages, etc) it is encouraged to use its 'consolidate' tool.\"",
    "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works",
    "post_date": "2026-06-16",
    "tense": "present / standing mechanism"
  },
  "compute_cost": {
    "status": "one current figure, explicitly time-scoped; earlier snapshots describe different, earlier periods rather than conflicting",
    "quote_current": {"text": "\"Currently, on the order of $10k per month in AI compute and infrastructure costs.\"", "source": "https://aivillageblog.substack.com/p/how-the-ai-village-works", "post_date": "2026-06-16", "tense": "explicitly \"Currently\""},
    "earlier_snapshots": [
      {"text": "\"about, like, 3k per month\"", "period_described": "2025 launch era, ~2 hrs/day", "source": "https://www.cognitiverevolution.ai/the-ai-village-previewing-the-giga-agent-future-with-adam-binksmith-founder-of-ai-digest/"},
      {"text": "\"September operations cost approximately $4,700\"", "period_described": "a September (year as framed by the TIME article; not independently re-confirmed beyond that article's own framing)", "source": "https://time.com/7330795/ai-village-chatgpt-gemini-claude/"}
    ]
  },
  "staff_count": {
    "status": "one verbatim figure, plausibly (not certainly) corroborated by a separate, undated team page",
    "quote": "\"We're a small team, currently four technical staff, so we expect you'll have an outsized impact compared to at bigger orgs.\"",
    "source": "https://aivillageblog.substack.com/p/work-on-the-ai-village",
    "post_date": "2026-08-28",
    "tense": "explicitly \"currently\"",
    "corroboration": "sage-future.org lists exactly four named AI Digest team members (Adam Binksmith - Director, George Ingebretsen, Shoshannah Tekofsky, Zak Miller) (https://sage-future.org/), consistent with but not explicitly dated to confirm the same headcount at the same moment."
  },
  "coefficient_giving_award": {
    "status": "one clear, dated, verbatim figure",
    "quote": "\"We've been awarded $12.6M from Coefficient Giving to radically increase the scale and ambition of the AI Village.\"",
    "source": "https://aivillageblog.substack.com/p/work-on-the-ai-village",
    "post_date": "2026-08-28",
    "tense": "past/completed (\"have been awarded\"), funding forward-looking hiring",
    "corroboration": "A WebSearch snippet showed AI Digest's own X/Twitter account posting near-identical wording; not independently fetched in full by this dossier, so the Substack post remains the primary citation."
  },
  "gitlab_ci_minutes_outage": {
    "status": "confirmed on the timeline; only loosely dated",
    "quote": "\"the entire village's work grind to a halt for a day when GitLab's shared CI minutes simply ran out\"",
    "source": "https://theaidigest.org/village/timeline",
    "associated_goal_period": "2026-07-06 through at least 2026-09-04 (goal: 'Each agent: Maximize your assigned goal!', still active at research time)",
    "precision_limit": "Described as lasting 'a day' but no more specific single calendar date within the ~2-month period was given in the retrievable text beyond the period's July 6 start; this dossier reports that as the limit of source precision rather than guessing an exact date."
  }
},

